-- query_id: 01c87a19-0004-ea10-0000-7b7d001c3306
SELECT COALESCE(SUM(n-1),0) AS redundantes, COUNT_IF(n>1) AS claves_repetidas FROM (SELECT "TICKER","FECHA",COUNT(*) n FROM SILVER.SLV_PRECIOS_ACCIONES GROUP BY "TICKER","FECHA");

-- query_id: 01c87a19-0004-ea10-0000-7b7d001c330a
SELECT COUNT_IF(v>1) afectados,COUNT(*) total FROM (SELECT TICKER,FECHA,COUNT(DISTINCT ADJ_CLOSE) v FROM RAW.PRECIOS_DIARIOS GROUP BY 1,2);

-- query_id: 01c87a19-0004-ea10-0000-7b7d001c330e
SELECT COUNT_IF(hi/NULLIF(lo,0)-1>0.0001) afectados,COUNT(*) total FROM (SELECT TICKER,FECHA,MIN(ADJ_CLOSE) lo,MAX(ADJ_CLOSE) hi FROM RAW.PRECIOS_DIARIOS WHERE ADJ_CLOSE>0 GROUP BY 1,2);

-- query_id: 01c87a19-0004-ea3e-0000-7b7d001bf4ee
WITH p AS (SELECT * FROM RAW.PRECIOS_DIARIOS WHERE TICKER IS NOT NULL AND FECHA IS NOT NULL
  QUALIFY ROW_NUMBER() OVER(PARTITION BY UPPER(TRIM(TICKER)),FECHA ORDER BY INGESTA_TS DESC,LOTE_ID DESC)=1), r AS (SELECT TICKER, ADJ_CLOSE, LAG(ADJ_CLOSE) OVER(PARTITION BY TICKER ORDER BY FECHA) prev FROM p WHERE TICKER NOT LIKE '^%') SELECT COUNT_IF(ABS(LN(NULLIF(IFF(ADJ_CLOSE>0,ADJ_CLOSE,NULL),0)/NULLIF(IFF(prev>0,prev,NULL),0)))>0.4) afectados,COUNT_IF(ADJ_CLOSE>0 AND prev>0) total FROM r;

-- query_id: 01c87a19-0004-ea40-0000-7b7d001c152a
WITH p AS (SELECT * FROM RAW.PRECIOS_DIARIOS WHERE TICKER IS NOT NULL AND FECHA IS NOT NULL
  QUALIFY ROW_NUMBER() OVER(PARTITION BY UPPER(TRIM(TICKER)),FECHA ORDER BY INGESTA_TS DESC,LOTE_ID DESC)=1), lagged AS (SELECT TICKER,ADJ_CLOSE,LAG(ADJ_CLOSE) OVER(PARTITION BY TICKER ORDER BY FECHA) prev FROM p WHERE TICKER NOT LIKE '^%'), r AS (SELECT TICKER,LN(NULLIF(IFF(ADJ_CLOSE>0,ADJ_CLOSE,NULL),0)/NULLIF(IFF(prev>0,prev,NULL),0)) ret FROM lagged), quant AS (SELECT TICKER,PERCENTILE_CONT(0.25) WITHIN GROUP(ORDER BY ret) q1,PERCENTILE_CONT(0.75) WITHIN GROUP(ORDER BY ret) q3,COUNT(ret) n FROM r GROUP BY 1) SELECT COUNT_IF(r.ret<q.q1-1.5*(q.q3-q.q1) OR r.ret>q.q3+1.5*(q.q3-q.q1)) afectados,COUNT(*) total FROM r JOIN quant q USING(TICKER) WHERE r.ret IS NOT NULL AND q.n>=20;

-- query_id: 01c87a19-0004-ea32-0000-7b7d001c244e
WITH p AS (SELECT * FROM RAW.PRECIOS_DIARIOS WHERE TICKER IS NOT NULL AND FECHA IS NOT NULL
  QUALIFY ROW_NUMBER() OVER(PARTITION BY UPPER(TRIM(TICKER)),FECHA ORDER BY INGESTA_TS DESC,LOTE_ID DESC)=1), lagged AS (SELECT TICKER,FECHA,ADJ_CLOSE,LAG(ADJ_CLOSE) OVER(PARTITION BY TICKER ORDER BY FECHA) prev,LAG(FECHA) OVER(PARTITION BY TICKER ORDER BY FECHA) prev_fecha FROM p WHERE TICKER NOT LIKE '^%'), r AS (SELECT TICKER,FECHA,LN(NULLIF(IFF(ADJ_CLOSE>0,ADJ_CLOSE,NULL),0)/NULLIF(IFF(prev>0,prev,NULL),0)) ret FROM lagged WHERE FECHA-prev_fecha<=7), med AS (SELECT TICKER,MEDIAN(ret) m,COUNT(ret) n FROM r GROUP BY 1), dev AS (SELECT r.TICKER,r.FECHA,r.ret,ABS(r.ret-med.m) d FROM r JOIN med USING(TICKER) WHERE r.ret IS NOT NULL AND med.n>=20), mad AS (SELECT TICKER,MEDIAN(d) mad FROM dev GROUP BY 1), z AS (SELECT dev.TICKER,dev.FECHA,dev.ret,0.6745*dev.d/NULLIF(mad.mad,0) z FROM dev JOIN mad USING(TICKER)) SELECT COUNT_IF(z>3.5) afectados,COUNT(*) total FROM z;

-- query_id: 01c87a19-0004-ea32-0000-7b7d001c2452
WITH p AS (SELECT * FROM RAW.PRECIOS_DIARIOS WHERE TICKER IS NOT NULL AND FECHA IS NOT NULL
  QUALIFY ROW_NUMBER() OVER(PARTITION BY UPPER(TRIM(TICKER)),FECHA ORDER BY INGESTA_TS DESC,LOTE_ID DESC)=1), lagged AS (SELECT TICKER,FECHA,ADJ_CLOSE,LAG(ADJ_CLOSE) OVER(PARTITION BY TICKER ORDER BY FECHA) prev,LAG(FECHA) OVER(PARTITION BY TICKER ORDER BY FECHA) prev_fecha FROM p WHERE TICKER NOT LIKE '^%'), r AS (SELECT TICKER,FECHA,LN(NULLIF(IFF(ADJ_CLOSE>0,ADJ_CLOSE,NULL),0)/NULLIF(IFF(prev>0,prev,NULL),0)) ret FROM lagged WHERE FECHA-prev_fecha<=7), med AS (SELECT TICKER,MEDIAN(ret) m,COUNT(ret) n FROM r GROUP BY 1), dev AS (SELECT r.TICKER,r.FECHA,r.ret,ABS(r.ret-med.m) d FROM r JOIN med USING(TICKER) WHERE r.ret IS NOT NULL AND med.n>=20), mad AS (SELECT TICKER,MEDIAN(d) mad FROM dev GROUP BY 1), z AS (SELECT dev.TICKER,dev.FECHA,dev.ret,0.6745*dev.d/NULLIF(mad.mad,0) z FROM dev JOIN mad USING(TICKER)) SELECT TICKER ticker,FECHA fecha,ROUND(ret,5) ret_log,ROUND(z,2) z_robusto FROM z WHERE z>3.5 ORDER BY z DESC LIMIT 30;

-- query_id: 01c87a19-0004-ea32-0000-7b7d001c2456
WITH p AS (SELECT * FROM RAW.PRECIOS_DIARIOS WHERE TICKER IS NOT NULL AND FECHA IS NOT NULL
  QUALIFY ROW_NUMBER() OVER(PARTITION BY UPPER(TRIM(TICKER)),FECHA ORDER BY INGESTA_TS DESC,LOTE_ID DESC)=1), lagged AS (SELECT TICKER,FECHA,ADJ_CLOSE,LAG(ADJ_CLOSE) OVER(PARTITION BY TICKER ORDER BY FECHA) prev,LAG(FECHA) OVER(PARTITION BY TICKER ORDER BY FECHA) prev_fecha FROM p WHERE TICKER NOT LIKE '^%'), r AS (SELECT TICKER,FECHA,LN(NULLIF(IFF(ADJ_CLOSE>0,ADJ_CLOSE,NULL),0)/NULLIF(IFF(prev>0,prev,NULL),0)) ret FROM lagged WHERE FECHA-prev_fecha<=7), med AS (SELECT TICKER,MEDIAN(ret) m,COUNT(ret) n FROM r GROUP BY 1), dev AS (SELECT r.TICKER,r.FECHA,r.ret,ABS(r.ret-med.m) d FROM r JOIN med USING(TICKER) WHERE r.ret IS NOT NULL AND med.n>=20), mad AS (SELECT TICKER,MEDIAN(d) mad FROM dev GROUP BY 1), z AS (SELECT dev.TICKER,dev.FECHA,dev.ret,0.6745*dev.d/NULLIF(mad.mad,0) z FROM dev JOIN mad USING(TICKER)) SELECT FECHA fecha,COUNT(*) acciones_marcadas,ROUND(AVG(ret),5) ret_log_promedio FROM z WHERE z>3.5 GROUP BY 1 ORDER BY 2 DESC LIMIT 20;

-- query_id: 01c87a19-0004-ea3e-0000-7b7d001bf4f2
WITH p AS (SELECT * FROM RAW.PRECIOS_DIARIOS WHERE TICKER IS NOT NULL AND FECHA IS NOT NULL
  QUALIFY ROW_NUMBER() OVER(PARTITION BY UPPER(TRIM(TICKER)),FECHA ORDER BY INGESTA_TS DESC,LOTE_ID DESC)=1), vida AS (SELECT TICKER,MIN(FECHA) inicio,MAX(FECHA) fin FROM p WHERE TICKER NOT LIKE '^%' GROUP BY 1), grilla AS (SELECT v.TICKER,c.FECHA FROM vida v JOIN BRONZE.CALENDARIO_NYSE c ON c.FECHA BETWEEN v.inicio AND v.fin) SELECT COUNT_IF(p.TICKER IS NULL) afectados,COUNT(*) total FROM grilla g LEFT JOIN p ON g.TICKER=p.TICKER AND g.FECHA=p.FECHA;

-- query_id: 01c87a19-0004-ea10-0000-7b7d001c3312
WITH p AS (SELECT * FROM RAW.PRECIOS_DIARIOS WHERE TICKER IS NOT NULL AND FECHA IS NOT NULL
  QUALIFY ROW_NUMBER() OVER(PARTITION BY UPPER(TRIM(TICKER)),FECHA ORDER BY INGESTA_TS DESC,LOTE_ID DESC)=1) SELECT COUNT_IF(c.FECHA IS NULL) afectados,COUNT(*) total FROM p LEFT JOIN BRONZE.CALENDARIO_NYSE c ON p.FECHA=c.FECHA WHERE p.TICKER NOT LIKE '^%' AND p.FECHA>='2010-01-01';

-- query_id: 01c87a19-0004-ea25-0000-7b7d001c054e
WITH c AS (SELECT * FROM RAW.COMPOSICION_SP500 QUALIFY DENSE_RANK() OVER(ORDER BY INGESTA_TS DESC,LOTE_ID DESC)=1) SELECT COUNT_IF(ARRAY_SIZE(SPLIT(TICKERS,','))<495) afectados,COUNT(*) total FROM c WHERE FECHA>='2010-01-01';

-- query_id: 01c87a19-0004-ea25-0000-7b7d001c0552
WITH l AS (SELECT * FROM RAW.LISTADOS_BOLSA QUALIFY DENSE_RANK() OVER(ORDER BY INGESTA_TS DESC,LOTE_ID DESC)=1) SELECT COUNT_IF(n>1) afectados,COUNT(*) total FROM (SELECT SIMBOLO,COUNT(DISTINCT CODIGO_BOLSA) n FROM l GROUP BY 1);

-- query_id: 01c87a19-0004-ea25-0000-7b7d001c0556
SELECT COUNT_IF(ESTADO='SIN_DATOS') afectados,COUNT(*) total FROM RAW.INGESTA_LOG;

-- query_id: 01c87a19-0004-ea32-0000-7b7d001c245a
SELECT COUNT_IF(ESTADO='ERROR') afectados,COUNT(*) total FROM RAW.INGESTA_LOG;

-- query_id: 01c87a19-0004-ea32-0000-7b7d001c245e
SELECT YEAR(FECHA) anio, CASE WHEN TICKER='^IRX' THEN 'tasa' WHEN TICKER LIKE '^%' THEN 'indice' ELSE 'accion' END segmento,COUNT(*) filas,COUNT_IF(ADJ_CLOSE IS NULL) cierre_ajustado_nulo,COUNT_IF(VOLUME IS NULL) volumen_nulo,COUNT_IF(VOLUME=0) volumen_cero,ROUND(100.0*COUNT_IF(ADJ_CLOSE IS NULL)/NULLIF(COUNT(*),0),6) cierre_nulo_pct FROM RAW.PRECIOS_DIARIOS GROUP BY 1,2 ORDER BY 1,2;